10: def review_schedule(request: Any) -> dict[str, Any]:
11:     """Return an exact assignment comparison with ordered, named explanations."""
12:     names, matrix, current_windows = prepare_request(request)
13:     current = evaluate_windows(names, matrix, current_windows)
14:     _, (first, second) = maxcut_bruteforce(matrix)
15:     proposed = evaluate_windows(names, matrix, [first, second])
16:     return {"equipment_count": len(names), "requirement_count": len(request["requirements"]),
17:             "current": current, "proposed": proposed,
18:             "changes": compare_assignments(names, current, proposed)}
