20: 
21: if __name__ == "__main__":
22:     print(json.dumps(review_schedule(json.load(sys.stdin)), indent=2))

FILE maintenance.py
1: """Validation, assignment calculations and reporting for two maintenance windows."""
2: 
3: from typing import Any
4: 
5: 
6: def prepare_request(request: Any) -> tuple[list[str], list[list[int]], list[list[int]]]:
7:     """Validate all data before evaluating either assignment; never mutate input."""
8:     required = {"equipment", "requirements", "current_windows"}
9:     if not isinstance(request, dict) or set(request) != required:
10:         raise ValueError("Expected equipment, requirements and current_windows")
11:     names = request["equipment"]
12:     if not isinstance(names, list) or len(names) > 16:
13:         raise ValueError("equipment must be a list of at most 16 names")
14:     if any(not isinstance(name, str) or not name for name in names) or len(set(names)) != len(names):
15:         raise ValueError("equipment names must be unique nonempty strings")
16:     index = {name: i for i, name in enumerate(names)}
17:     requirements = request["requirements"]
18:     if not isinstance(requirements, list):
19:         raise ValueError("requirements must be a list")
20:     matrix = [[0] * len(names) for _ in names]
21:     for item in requirements:
22:         if not isinstance(item, dict) or set(item) != {"first", "second", "weight"}:
23:             raise ValueError("Each requirement needs first, second and weight")
24:         first, second, weight = item["first"], item["second"], item["weight"]
25:         if not isinstance(first, str) or not isinstance(second, str):
26:             raise ValueError("Requirement endpoints must be names")
27:         if first not in index or second not in index or first == second:
28:             raise ValueError("Requirement endpoints must be distinct known equipment")
29:         if type(weight) is not int or weight < 0:
30:             raise ValueError("weight must be a nonnegative integer, not bool")
31:         u, v = index[first], index[second]
32:         matrix[u][v] += weight
33:         matrix[v][u] += weight
34:     windows = request["current_windows"]
35:     if not isinstance(windows, list) or len(windows) != 2:
36:         raise ValueError("current_windows must contain exactly two lists")
37:     seen: set[str] = set()
38:     current = []
39:     for window in windows:
40:         if not isinstance(window, list):
41:             raise ValueError("Each window must be a list")
42:         positions = []
43:         for name in window:
44:             if not isinstance(name, str) or name not in index or name in seen:
45:                 raise ValueError("Each equipment name must occur exactly once")
46:             seen.add(name)
47:             positions.append(index[name])
48:         current.append(sorted(positions))
49:     if seen != set(names):
50:         raise ValueError("Every equipment item must be assigned")
51:     return list(names), matrix, current
52: 
53: 
54: def evaluate_windows(
55:     names: list[str], matrix: list[list[int]], windows: list[list[int]]
56: ) -> dict[str, Any]:
57:     """Describe a validated assignment, including positive-weight conflicts."""
58:     side = {position: group for group, members in enumerate(windows) for position in members}
59:     conflicts = []
60:     total_weight = 0
61:     for u in range(len(names)):
62:         for v in range(u + 1, len(names)):
63:             weight = matrix[u][v]
64:             total_weight += weight
65:             if weight > 0 and side[u] == side[v]:
66:                 conflicts.append({"first": names[u], "second": names[v], "weight": weight})
67:     conflict_weight = sum(item["weight"] for item in conflicts)
68:     return {"windows": [[names[i] for i in members] for members in windows],
69:             "conflict_weight": conflict_weight,
70:             "separated_weight": total_weight - conflict_weight,
71:             "conflicts": conflicts}
72: 
73: 
74: def maxcut_bruteforce(adj):
75:     n=len(adj)
76:     best=-1
77:     best_part=None
78:     for mask in range(1<<n):
79:         left=[i for i in range(n) if (mask>>i)&1]
80:         right=[i for i in range(n) if not (mask>>i)&1]
81:         val=0
82:         for i in range(n):
83:             for j in range(i+1,n):
84:                 if adj[i][j]!=0 and ((i in left and j in right) or (i in right and j in left)):
85:                     val+=adj[i][j]
86:         if val>best:
87:             best=val
88:             best_part=(left,right)
89:     return best,best_part
90: 
91: 
92: def compare_assignments(
93:     names: list[str], current: dict[str, Any], proposed: dict[str, Any]
94: ) -> dict[str, Any]:
95:     """Report changes without adding movement cost to the selection objective."""
96:     old_side = {name: group for group, members in enumerate(current["windows"]) for name in members}
97:     new_side = {name: group for group, members in enumerate(proposed["windows"]) for name in members}
98:     moved = [{"equipment": name, "from_window": old_side[name], "to_window": new_side[name]}
99:              for name in names if old_side[name] != new_side[name]]
100:     old_pairs = {(item["first"], item["second"]) for item in current["conflicts"]}
101:     new_pairs = {(item["first"], item["second"]) for item in proposed["conflicts"]}
102:     return {"moved_equipment": moved,
103:             "conflict_reduction": current["conflict_weight"] - proposed["conflict_weight"],
104:             "resolved_conflicts": [item.copy() for item in current["conflicts"]
105:                                    if (item["first"], item["second"]) not in new_pairs],
106:             "introduced_conflicts": [item.copy() for item in proposed["conflicts"]
107:                                      if (item["first"], item["second"]) not in old_pairs]}

